// Permission catalogue and seeded role defaults (ADR-0006). Source: docs/analysis/permissions-matrix.md.
// These are a CONFIGURABLE STARTING POINT, not a Mobily-approved access policy. The database is the runtime
// source of truth (role, permission, role_permission tables); the P1 seed migration inserts exactly these rows,
// and a unit test in @mth/db asserts the seed matches this file.

export const PERMISSION_CATEGORIES = ["read", "write", "configure", "business_approval", "finance_validation"] as const;
export type PermissionCategory = (typeof PERMISSION_CATEGORIES)[number];

export const PERMISSIONS = {
  "organization.read": "read",
  "organization.manage": "configure",
  "business_unit.read": "read",
  "business_unit.manage": "configure",
  "user.read": "read",
  "user.manage": "configure",
  "role.read": "read",
  "access.read": "read",
  "access.assign": "configure",
  "transformation.read": "read",
  "transformation.create": "write",
  "transformation.update": "write",
  "transformation.archive": "write",
  "audit.read": "read",
  // Catalogue entries that exist from P1 so separation-of-duties constraints are enforced from the start
  // (ADR-0006: a technical_admin role can never hold these). No P1 route uses them.
  "gate.decide": "business_approval",
  "finance.validate": "finance_validation",
} as const satisfies Record<string, PermissionCategory>;
export type Permission = keyof typeof PERMISSIONS;
export const PERMISSION_CODES = Object.keys(PERMISSIONS) as Permission[];

export const ROLE_KINDS = ["source", "implementation", "technical_admin"] as const;
export type RoleKind = (typeof ROLE_KINDS)[number];

export interface RoleDefinition {
  readonly kind: RoleKind;
  /** A grant at a wider scope also applies to narrower scopes inside it (permissions matrix rule 1). */
  readonly inheritsDownward: boolean;
  readonly permissions: readonly Permission[];
}

const BASE_READ = ["organization.read", "business_unit.read", "role.read", "transformation.read"] as const;

export const ROLES = {
  SP: { kind: "source", inheritsDownward: false, permissions: [...BASE_READ, "gate.decide"] },
  TL: {
    kind: "source",
    inheritsDownward: false,
    permissions: [
      ...BASE_READ,
      "transformation.create",
      "transformation.update",
      "transformation.archive",
      "audit.read",
    ],
  },
  BO: { kind: "source", inheritsDownward: false, permissions: [...BASE_READ, "gate.decide"] },
  WL: { kind: "source", inheritsDownward: false, permissions: [...BASE_READ] },
  FIN: { kind: "source", inheritsDownward: false, permissions: [...BASE_READ, "finance.validate"] },
  TO: {
    kind: "source",
    inheritsDownward: true,
    permissions: [
      ...BASE_READ,
      "transformation.create",
      "transformation.update",
      "transformation.archive",
      "audit.read",
    ],
  },
  KDS: { kind: "implementation", inheritsDownward: false, permissions: [...BASE_READ] },
  TD: { kind: "implementation", inheritsDownward: false, permissions: [...BASE_READ] },
  CM: { kind: "implementation", inheritsDownward: false, permissions: [...BASE_READ] },
  SEC: { kind: "implementation", inheritsDownward: false, permissions: [...BASE_READ] },
  AUD: {
    kind: "implementation",
    inheritsDownward: true,
    permissions: [...BASE_READ, "audit.read", "user.read", "access.read"],
  },
  // Technical administrators: configuration only, no business-record access and never an approver
  // (REQ-S10-003, REQ-S06-010; permissions matrix: Transformation row "— (technical support only)").
  ADM_TECH: {
    kind: "technical_admin",
    inheritsDownward: false,
    permissions: [
      "organization.read",
      "organization.manage",
      "business_unit.read",
      "business_unit.manage",
      "role.read",
    ],
  },
  ADM_ACCESS: {
    kind: "technical_admin",
    inheritsDownward: false,
    permissions: [
      "organization.read",
      "business_unit.read",
      "role.read",
      "user.read",
      "user.manage",
      "access.read",
      "access.assign",
    ],
  },
  ADM_METHOD: { kind: "technical_admin", inheritsDownward: false, permissions: ["organization.read", "role.read"] },
} as const satisfies Record<string, RoleDefinition>;
export type RoleCode = keyof typeof ROLES;
export const ROLE_CODES = Object.keys(ROLES) as RoleCode[];

/** Categories a technical_admin role may never hold (enforced again by a DB trigger, ADR-0006). */
export const APPROVAL_CATEGORIES: readonly PermissionCategory[] = ["business_approval", "finance_validation"];
// API module map and dependency-direction rules (ADR-0002). backend-workflow-engineer adds an architecture
// test that parses imports under src/modules/** and fails when a module imports anything not allowed here.
//
// Rules:
//  1. A module may import only its own files, the modules listed in `dependsOn`, and the shared packages
//     (@mth/shared, @mth/config, @mth/db). Cross-module calls go through the other module's `index.ts`.
//  2. Every module may call `access` (the single policy function) and `audit` (the audit writer).
//  3. No cycles. `platform` (HTTP plumbing: request IDs, problem+json, ETag/If-Match, CSRF, rate limits)
//     depends on nothing and nothing depends on route files.

export const API_MODULES = {
  platform: { responsibility: "HTTP plumbing, errors, request IDs, health/readiness", dependsOn: [] },
  audit: { responsibility: "Append-only audit writer and audit queries", dependsOn: ["platform"] },
  identity: {
    responsibility: "OIDC login, dev login, sessions, CSRF, /me",
    dependsOn: ["platform", "audit", "access", "organization"],
  },
  access: {
    responsibility: "Roles, permissions, scoped assignments, delegation, the policy function",
    dependsOn: ["platform", "audit"],
  },
  organization: {
    responsibility: "Organizations, business units, calendars (later)",
    dependsOn: ["platform", "audit", "access"],
  },
  transformations: {
    responsibility: "Transformation records and workspace header data",
    dependsOn: ["platform", "audit", "access", "organization", "jobs"],
  },
  methodology: {
    responsibility: "Methodology/form/formula versions and publishing (P2/P5)",
    dependsOn: ["platform", "audit", "access"],
  },
  workflows: {
    responsibility: "Gates, approvals, decisions, SoD rules (P2+)",
    dependsOn: ["platform", "audit", "access", "transformations", "methodology"],
  },
  kpi: {
    responsibility: "KPI and benefit calculations via @mth/calc (P4)",
    dependsOn: ["platform", "audit", "access", "transformations", "methodology"],
  },
  reporting: {
    responsibility: "Report snapshots and exports via @mth/reporting (P5)",
    dependsOn: ["platform", "audit", "access", "transformations", "kpi"],
  },
  evidence: {
    responsibility: "Evidence metadata and the storage adapter (P2/P6)",
    dependsOn: ["platform", "audit", "access"],
  },
  jobs: { responsibility: "Outbox writer and job/automation administration views", dependsOn: ["platform", "audit"] },
  admin: {
    responsibility: "Administration endpoints composed from other modules",
    dependsOn: ["platform", "audit", "access", "organization", "identity", "jobs"],
  },
} as const satisfies Record<string, { responsibility: string; dependsOn: readonly string[] }>;

export type ApiModule = keyof typeof API_MODULES;

/**
 * Modules that exist in P1 (each with a public index.ts and, for the §16 business modules, its own test suite).
 * `workflows`, `kpi` and `reporting` are P1 SCAFFOLDS (D-048): boundary, public interface, wiring hook and suite exist
 * now, their business behaviour lands in P2 / P4 / P5, and their hooks register no routes yet. `methodology` and
 * `evidence` remain reserved names (no directory yet), so later stages add code, not new boundaries.
 */
export const P1_MODULES: readonly ApiModule[] = [
  "platform",
  "audit",
  "identity",
  "access",
  "organization",
  "transformations",
  "jobs",
  "admin",
  "workflows",
  "kpi",
  "reporting",
];

/** The six §16 business modules (master prompt M0308; REQ-S16-003 / A12): each exists with its own test suite. */
export const SECTION16_MODULES = {
  "identity/access": ["identity", "access"],
  transformations: ["transformations"],
  workflows: ["workflows"],
  "formulas/KPI": ["kpi"],
  reporting: ["reporting"],
  admin: ["admin"],
} as const satisfies Record<string, readonly ApiModule[]>;

/** P1 scaffolds: they exist, but deliver behaviour in a later stage and register no routes in P1 (D-048). */
export const P1_SCAFFOLD_MODULES = ["workflows", "kpi", "reporting"] as const satisfies readonly ApiModule[];

