#!/usr/bin/env node
// Validates the OpenAPI 3.1 contract (ADR-0007, acceptance check 3).
//  1. @apidevtools/swagger-parser (pinned devDependency) validates the document against the OAS 3.1 schema
//     and resolves every $ref. Runs fully offline.
//  2. Project rules: unique operationIds, every mutating operation requires the CSRF scheme, every
//     If-Match operation documents 409 + 428, every error response uses application/problem+json.
// Usage: node scripts/openapi-lint.mjs docs/api/openapi.yaml
import SwaggerParser from "@apidevtools/swagger-parser";

const file = process.argv[2] ?? "docs/api/openapi.yaml";
const problems = [];
let api;
try {
  api = await SwaggerParser.validate(file);
} catch (err) {
  console.error(`FAIL ${file}: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
}
if (!String(api.openapi).startsWith("3.1")) problems.push(`openapi must be 3.1.x, got ${api.openapi}`);

const UNSAFE = new Set(["post", "put", "patch", "delete"]);
const PUBLIC_UNSAFE = new Set(["devLogin"]); // login-CSRF is handled by the Origin check (ADR-0005)
const seen = new Set();
for (const [path, item] of Object.entries(api.paths ?? {})) {
  for (const [method, op] of Object.entries(item)) {
    if (!["get", "put", "post", "patch", "delete"].includes(method)) continue;
    const id = op.operationId;
    if (!id) problems.push(`${method.toUpperCase()} ${path}: missing operationId`);
    else if (seen.has(id)) problems.push(`duplicate operationId ${id}`);
    else seen.add(id);
    if (!path.startsWith("/api/v1/") && !["/healthz", "/readyz"].includes(path))
      problems.push(`${path}: outside /api/v1`);
    if (UNSAFE.has(method) && !PUBLIC_UNSAFE.has(id)) {
      const sec = op.security ?? api.security ?? [];
      if (!sec.some((req) => "csrfToken" in req && "sessionCookie" in req))
        problems.push(`${id}: unsafe method without sessionCookie+csrfToken`);
    }
    const params = [...(item.parameters ?? []), ...(op.parameters ?? [])];
    if (params.some((p) => p.in === "header" && p.name === "If-Match")) {
      for (const code of ["409", "428"])
        if (!op.responses?.[code]) problems.push(`${id}: If-Match operation lacks ${code}`);
    }
    for (const [code, resp] of Object.entries(op.responses ?? {})) {
      if (Number(code) >= 400 && code !== "503" && !resp.content?.["application/problem+json"])
        problems.push(`${id} ${code}: error response is not application/problem+json`);
    }
  }
}
if (problems.length) {
  console.error(`FAIL ${file} (${problems.length} problem(s))`);
  for (const p of problems) console.error(`  - ${p}`);
  process.exit(1);
}
console.log(`PASS ${file}: OpenAPI ${api.openapi}, ${seen.size} operations`);
components:
  securitySchemes:
    sessionCookie:
      type: apiKey
      in: cookie
      name: __Host-mth_session
      description: |
        Opaque server-side session ID (256-bit random; only its SHA-256 is stored). HttpOnly, Secure,
        SameSite=Lax, Path=/. Named `mth_session` (without the `__Host-` prefix) only for an http://localhost base URL in development.
        Idle timeout SESSION_IDLE_MINUTES (default 30), absolute SESSION_ABSOLUTE_HOURS (default 10).
    csrfToken:
      type: apiKey
      in: header
      name: X-CSRF-Token
      description: Per-session synchronizer token from `GET /api/v1/me` (`csrfToken`). Required on every unsafe method, together with a same-origin `Origin` header.

  parameters:
    IfMatch:
      name: If-Match
      in: header
      required: true
      description: The ETag (`"<version>"`) of the representation being changed. A missing header gives 428; a stale one gives 409.
      schema: { type: string, pattern: '^"[1-9][0-9]{0,9}"$' }
    IdempotencyKey:
      name: Idempotency-Key
      in: header
      required: false
      description: Client-generated key (UUID recommended). A retried create with the same key and body returns the original result for 24 hours; the same key with a different body gives 422.
      schema: { type: string, minLength: 8, maxLength: 128, pattern: "^[A-Za-z0-9_-]+$" }
    Cursor:
      name: cursor
      in: query
      required: false
      description: Opaque cursor from a previous page's `nextCursor`. It is bound to the sort order and filters; reuse with other filters gives 400.
      schema: { type: string, maxLength: 512 }
    Limit:
      name: limit
      in: query
      required: false
      schema: { type: integer, minimum: 1, maximum: 100, default: 25 }
    OrganizationId:
      name: organizationId
      in: path
      required: true
      schema: { $ref: "#/components/schemas/Uuid" }
    BusinessUnitId:
      name: businessUnitId
      in: path
      required: true
      schema: { $ref: "#/components/schemas/Uuid" }
    UserId:
      name: userId
      in: path
      required: true
      schema: { $ref: "#/components/schemas/Uuid" }
    AssignmentId:
      name: assignmentId
      in: path
      required: true
      schema: { $ref: "#/components/schemas/Uuid" }
    TransformationId:
      name: transformationId
      in: path
      required: true
      schema: { $ref: "#/components/schemas/Uuid" }

  headers:
    X-Request-Id:
      description: Request correlation ID (echoed from a valid inbound header or generated), also in every log line and audit event.
      schema: { type: string, maxLength: 128 }
    ETag:
      description: Strong entity tag `"<version>"`.
      schema: { type: string, pattern: '^"[1-9][0-9]{0,9}"$' }
    Location:
      schema: { type: string }
    Set-Cookie:
      schema: { type: string }
    Retry-After:
      schema: { type: integer, minimum: 0 }

  responses:
    ValidationError:
      description: Request failed schema validation (`urn:mth:problem:validation`), with field errors.
      content:
        application/problem+json:
          schema: { $ref: "#/components/schemas/Problem" }
    Unauthenticated:
      description: No valid session (`urn:mth:problem:unauthenticated`).
      content:
        application/problem+json:
          schema: { $ref: "#/components/schemas/Problem" }
    Forbidden:
      description: The caller can see the resource but lacks the permission, or the CSRF/Origin check failed (`forbidden` or `csrf`).
      content:
        application/problem+json:
          schema: { $ref: "#/components/schemas/Problem" }
    NotFound:
      description: The resource does not exist or the caller may not read it (`urn:mth:problem:not-found`).
      content:
        application/problem+json:
          schema: { $ref: "#/components/schemas/Problem" }
    VersionConflict:
      description: If-Match is stale (`urn:mth:problem:version-conflict`). `currentVersion` holds the server's version; nothing was written.
      content:
        application/problem+json:
          schema: { $ref: "#/components/schemas/Problem" }
    Duplicate:
      description: A uniqueness rule was violated, e.g. a code already used in the organization (`urn:mth:problem:duplicate`).
      content:
        application/problem+json:
          schema: { $ref: "#/components/schemas/Problem" }
    BusinessRule:
      description: A business rule rejected the change, e.g. an invalid status transition, an archived record, or a technical admin made an approver (`invalid-transition` or `validation`).
      content:
        application/problem+json:
          schema: { $ref: "#/components/schemas/Problem" }
    PreconditionRequired:
      description: If-Match header missing (`urn:mth:problem:precondition-required`).
      content:
        application/problem+json:
          schema: { $ref: "#/components/schemas/Problem" }
    RateLimited:
      description: Too many requests (`urn:mth:problem:rate-limited`).
      headers:
        Retry-After: { $ref: "#/components/headers/Retry-After" }
      content:
        application/problem+json:
          schema: { $ref: "#/components/schemas/Problem" }

  schemas:
    Uuid:
      type: string
      format: uuid
      description: UUIDv7 (time-ordered), generated by the application.
    Timestamp:
      type: string
      format: date-time
      description: RFC 3339 instant in UTC.

