/* Scratch-only test shim (never committed): postgres refuses euid 0, and this sandbox maps only uid 0.
   Report a non-root uid to postgres, and report files owned by uid 0 as owned by that uid. */
#define _GNU_SOURCE
#include <sys/types.h>
#include <sys/stat.h>
#include <dlfcn.h>
#define FAKE 4242
uid_t geteuid(void){return FAKE;} uid_t getuid(void){return FAKE;}
int stat(const char *p, struct stat *s){ static int(*r)(const char*,struct stat*); if(!r) r=dlsym(RTLD_NEXT,"stat"); int x=r(p,s); if(!x&&s->st_uid==0) s->st_uid=FAKE; return x;}
int lstat(const char *p, struct stat *s){ static int(*r)(const char*,struct stat*); if(!r) r=dlsym(RTLD_NEXT,"lstat"); int x=r(p,s); if(!x&&s->st_uid==0) s->st_uid=FAKE; return x;}
int fstat(int f, struct stat *s){ static int(*r)(int,struct stat*); if(!r) r=dlsym(RTLD_NEXT,"fstat"); int x=r(f,s); if(!x&&s->st_uid==0) s->st_uid=FAKE; return x;}
EOF
gcc -shared -fPIC -o $PGD/fakeuid.so $PGD/fakeuid.c -ldl && echo built; export PGBIN=/usr/lib/postgresql/16/bin; LD_PRELOAD=$PGD/fakeuid.so $PGBIN/initdb -D $PGD/data -U postgres --auth=trust -E UTF8 > $PGD/initdb.log 2>&1; echo init=$?; tail -2 $PGD/initdb.log

